import { Anchor, CellCanvas, HorizontalAnchor, VerticalAnchor } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function matrixEqual(actual: string[][], expected: string[][], message: string): void {
  equal(actual.length, expected.length, `${message}: height`);
  expected.forEach((row, y) => {
    equal(actual[y].length, row.length, `${message}: width ${y}`);
    row.forEach((value, x) => equal(actual[y][x], value, `${message}: ${x},${y}`));
  });
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof TypeError, message); return; }
  throw new Error(`${message}: did not throw`);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { assert(error instanceof RangeError, message); return; }
  throw new Error(`${message}: did not throw`);
}

for (const bad of [0, -1, 1.5, Number.MAX_SAFE_INTEGER + 1, Infinity, NaN]) {
  throwsRange(() => new CellCanvas(bad, 1), 'invalid width');
  throwsRange(() => new CellCanvas(1, bad), 'invalid height');
}
throwsType(() => new CellCanvas(1, 1, 3 as unknown as string), 'invalid empty value');

const canvas = new CellCanvas(5, 2, '.');
matrixEqual(canvas.snapshot(), [['.', '.', '.', '.', '.'], ['.', '.', '.', '.', '.']], 'initial grid');
const values = ['A', 'B'];
canvas.fillColumns(values);
equal(values.join(','), 'A,B', 'fill input unchanged');
matrixEqual(canvas.snapshot(), [['A', 'A', 'B', 'B', 'B'], ['A', 'A', 'B', 'B', 'B']], 'proportional fill');

const narrow = new CellCanvas(2, 1, '-');
narrow.fillColumns(['a', 'b', 'c', 'd']);
matrixEqual(narrow.snapshot(), [['a', 'c']], 'more values than columns');
throwsType(() => canvas.fillColumns([]), 'empty values');
throwsType(() => canvas.fillColumns(['ok', 1 as unknown as string]), 'non-string value');
matrixEqual(canvas.snapshot(), [['A', 'A', 'B', 'B', 'B'], ['A', 'A', 'B', 'B', 'B']], 'invalid fill is atomic');

const initial: Anchor = canvas.getAnchor();
equal(initial.horizontal, 'left', 'initial horizontal anchor');
equal(initial.vertical, 'top', 'initial vertical anchor');
(initial as { horizontal: HorizontalAnchor; vertical: VerticalAnchor }).horizontal = 'right';
equal(canvas.getAnchor().horizontal, 'left', 'anchor object is copied');
canvas.setAnchor('center', 'middle');
const anchorA = canvas.getAnchor();
const anchorB = canvas.getAnchor();
equal(anchorA.horizontal, 'center', 'set horizontal anchor');
equal(anchorA.vertical, 'middle', 'set vertical anchor');
assert(anchorA !== anchorB, 'anchor results are fresh');
throwsType(() => canvas.setAnchor('wide' as HorizontalAnchor, 'top'), 'invalid horizontal anchor');
throwsType(() => canvas.setAnchor('left', 'deep' as VerticalAnchor), 'invalid vertical anchor');
equal(canvas.getAnchor().horizontal, 'center', 'invalid anchor leaves state');

canvas.clearArea(1, 0, 2, 1);
matrixEqual(canvas.snapshot(), [['A', '.', '.', 'B', 'B'], ['A', 'A', 'B', 'B', 'B']], 'explicit clear');
canvas.clearArea(4, 1);
matrixEqual(canvas.snapshot(), [['A', '.', '.', 'B', 'B'], ['A', 'A', 'B', 'B', '.']], 'omitted size uses remainder');
const beforeNoop = canvas.snapshot();
canvas.clearArea(5, 2, 0, 0);
matrixEqual(canvas.snapshot(), beforeNoop, 'zero-sized boundary clear');
const beforeInvalid = canvas.snapshot();
for (const call of [
  () => canvas.clearArea(-1, 0, 1, 1),
  () => canvas.clearArea(0, 0, 6, 1),
  () => canvas.clearArea(5, 0, 1, 0),
  () => canvas.clearArea(0, 0, 1.5, 1),
]) throwsRange(call, 'invalid rectangle');
matrixEqual(canvas.snapshot(), beforeInvalid, 'invalid clears are atomic');
canvas.clearArea();
matrixEqual(canvas.snapshot(), [['.', '.', '.', '.', '.'], ['.', '.', '.', '.', '.']], 'clear whole grid');
const snap = canvas.snapshot();
snap[0][0] = 'mutated';
snap.push(['extra']);
matrixEqual(canvas.snapshot(), [['.', '.', '.', '.', '.'], ['.', '.', '.', '.', '.']], 'snapshot is deeply copied');

